// 原围城阶段在课程前：严格XP前界、未来半日/未知写者拒绝及旧接敌读不变的必要组件。
#include "resident/domains/growth/growth_siege_engineering_history.hpp"
#include "resident/domains/growth/growth_military_entry_history.hpp"
#include "resident/storage/common_codec.hpp"
#include <iostream>
#include <stdexcept>
#include <type_traits>
using namespace hanmo::resident;
namespace {Integer checks=0;void check(bool value,const char* message){++checks;if(!value)throw std::runtime_error(message);}
StudyFact lesson(Integer tick,Integer before,Integer gain){StudyFact f;f.actor_id="commander";f.start_tick=tick-1;f.phase="completed";f.completed_tick=tick;f.terms.student_id=f.actor_id;f.terms.skill_id="fortification";f.terms.xp_before=before;f.terms.xp_limit=1200;f.terms.settlement_policy="per_lesson_v1";StudyLesson l;l.xp=gain;l.segment=StudySegment{1,tick,before,10000,gain,false,{},{}};f.lessons.push_back(l);return f;}
using Before=Outcome<GrowthSiegeEngineeringSkillObservation>(*)(const CommonStore&,const GrowthSiegeEngineeringHistoryContext&,const GrowthState&,const StableId&,Integer,const StableId&,const DynamicStepInput*);
static_assert(std::is_same_v<decltype(&read_growth_siege_engineering_skill_before_preparation),Before>);
}
int main(){try{
 auto shared=std::make_shared<CommonCatalog>();shared->extended_skills=true;shared->actor_ids={"commander"};shared->actor_initial_birth.insert("commander",-14400);FamilyCatalog catalog;IdentityPrototype original;original.skills.extended.emplace();original.skills.extended->fortification=290;catalog.prototypes.insert("commander",original);FamilyState family;GrowthSiegeEngineeringHistoryContext context{*shared,catalog,family,nullptr};
 CommonState seed;seed.identity.tick=4;seed.next_instance_id=200;ActorRecord actor;actor.id="commander";actor.skills=original.skills;actor.skills.extended->fortification=335;seed.actors.insert(actor.id,actor);CommonStore c(seed,shared);GrowthState growth;
 auto first=lesson(3,290,10);first.lessons[0].segment->adjustment=StudyPerformanceAdjustment{3,300,15000,5,{}};growth.facts.insert("action:80",first);c.state().facts.insert("action:80",{"action:80","skill_study","cultivation"});c.state().facts.insert("military_siege_engineering:7",{"military_siege_engineering:7","military_siege_engineering_prepared","military"});growth.facts.insert("action:10",lesson(4,305,30));c.state().facts.insert("action:10",{"action:10","skill_study","cultivation"});c.state().facts.insert("military_siege_engineering:90",{"military_siege_engineering:90","military_siege_engineering_prepared","military"});
 const auto before=encode_common_state(c.state());auto now=read_growth_siege_engineering_skill(c,context,growth,"commander");check(now.ok&&now.value.skill_id=="fortification"&&now.value.experience==335&&now.value.level==2,"stable preview explains full current XP");check(now.value.causal_fact_ids==std::vector<StableId>{"action:80","action:10"},"actual Common causal order");auto early=read_growth_siege_engineering_skill_before_preparation(c,context,growth,"commander",3,"military_siege_engineering:7");check(early.ok&&early.value.experience==290&&early.value.level==1&&early.value.causal_fact_ids.empty(),"same tick automatic and zero-time credits both occur after siege");auto next=read_growth_siege_engineering_skill_before_preparation(c,context,growth,"commander",4,"military_siege_engineering:90");check(next.ok&&next.value.experience==305&&next.value.causal_fact_ids==std::vector<StableId>{"action:80"},"previous tick zero-time answer now belongs to engineering prefix");check(compare_boundary(before,encode_common_state(c.state())).exact(),"source read does not write Common");
 check(!read_growth_military_entry_qualification(c,context,growth,"commander","fortification").ok,"Land three skills not broadened");check(!read_growth_siege_engineering_skill_before_preparation(c,context,growth,"commander",3,{}).ok,"empty boundary refused");c.state().facts.find("military_siege_engineering:7")->domain="military_naval";check(!read_growth_siege_engineering_skill_before_preparation(c,context,growth,"commander",3,"military_siege_engineering:7").ok,"wrong domain refused");c.state().facts.find("military_siege_engineering:7")->domain="military";
 shared->extended_skills=false;check(!read_growth_siege_engineering_skill(c,context,growth,"commander").ok,"extended skill profile required");shared->extended_skills=true;c.state().actors.find("commander")->skills.extended->fortification=336;check(!read_growth_siege_engineering_skill(c,context,growth,"commander").ok,"unknown current XP cannot fill historical prefix");c.state().actors.find("commander")->skills.extended->fortification=335;growth.facts.erase("action:10");check(!read_growth_siege_engineering_skill(c,context,growth,"commander").ok,"missing permanent Study payload refused");
 CommonState hot_seed=seed;hot_seed.identity.tick=2;hot_seed.actors.find("commander")->skills.extended->fortification=300;CommonStore hot(hot_seed,shared);GrowthState hot_growth;hot_growth.facts.insert("action:80",lesson(3,290,10));hot.state().facts.insert("action:80",{"action:80","skill_study","cultivation"});hot.state().facts.insert("military_siege_engineering:7",{"military_siege_engineering:7","military_siege_engineering_prepared","military"});DynamicStepInput phase;phase.from_tick=2;phase.to_tick=3;
 auto prepared=read_growth_siege_engineering_skill_before_preparation(hot,context,hot_growth,"commander",3,"military_siege_engineering:7",&phase);check(prepared.ok&&prepared.value.source_identity.tick==2&&prepared.value.observed_tick==3&&prepared.value.experience==290,"strict phase prefix differs from later same-step Study");auto live=read_growth_siege_engineering_skill(hot,context,hot_growth,"commander",&phase);check(live.ok&&live.value.experience==290&&live.value.observed_tick==3,"hot current siege uses identical pre-actions cutoff");check(!read_growth_siege_engineering_skill_before_preparation(hot,context,hot_growth,"commander",3,"military_siege_engineering:7").ok,"stable read rejects future preparation");phase.to_tick=4;check(!read_growth_siege_engineering_skill(hot,context,hot_growth,"commander",&phase).ok,"invalid strict phase refused");
 std::cout<<"GROWTH_SIEGE_ENGINEERING_HISTORY "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
